// =====================================================================
// FACTORY CONFIG - ศูนย์รวมค่าตั้งค่าของโรงงานทั้งหมด
//
// วิธีแก้ค่า (เลือกอย่างใดอย่างหนึ่ง):
//   1. แก้ตัวเลข/ข้อความใน DEFAULTS ข้างล่างนี้ตรง ๆ (ง่ายสุด ใช้ได้ทุกแพลน)
//   2. หรือตั้งใน n8n Variables (Settings > Variables) ชื่อเดียวกัน - จะทับ DEFAULTS
//   3. หรือตั้ง environment variable (เฉพาะ self-hosted) - จะทับ DEFAULTS เช่นกัน
//
// แก้ที่ workflow 01 ตัวเดียวพอ: sub-workflow ทุกตัวรับ cfg ต่อจากแม่อัตโนมัติ
// =====================================================================
const DEFAULTS = {
  "OPENAI_MODEL_TEXT": "gpt-4.1",
  "GEMINI_API_BASE": "https://generativelanguage.googleapis.com",
  "GEMINI_MODEL_TEXT": "gemini-2.5-flash",
  "OPENAI_MODEL_IMAGE": "gpt-image-1",
  "OPENAI_IMAGE_QUALITY": "high",
  "IMAGE_QUALITY_COVER": "high",
  "IMAGE_QUALITY_PAGE": "medium",
  "IMAGE_QUALITY_SMALL": "low",
  "GENERATE_SEPARATE_PREVIEWS": "false",
  "PROMPT_VERSION": "v1.0.0",
  "ETSY_API_BASE": "https://openapi.etsy.com",
  "ETSY_API_KEY": "",
  "ETSY_SHOP_ID": "",
  "ETSY_LISTING_STATE": "draft",
  "ETSY_TAXONOMY_ID": 2078,
  "GDRIVE_ROOT_FOLDER_ID": "root",
  "DB_TYPE": "postgres",
  "DB_SQLITE_PATH": "/home/node/.n8n/adpf.db",
  "FACTORY_ROTATION": "planner,printable,canva,wallart,resume,spreadsheet,kids,svg",
  "ALERT_WEBHOOK_URL": "",
  "IDEA_TARGET_COUNT": 200,
  "IDEA_BATCH_SIZE": 25,
  "DUPLICATE_SIMILARITY_THRESHOLD": 0.62,
  "ALLOW_PRODUCT_REVISION": "false",
  "BUDGET_DAILY_USD": 20,
  "BUDGET_MONTHLY_USD": 300,
  "BUDGET_RUN_RESERVE_USD": 3,
  "OPENAI_IMAGE_UNIT_COST_USD": 0.19,
  "OPENAI_CHAT_RUN_COST_USD": 0.12,
  "OPENAI_PRICE_OVERRIDE_JSON": "{}",
  "LEARNING_WINDOW_DAYS": 30,
  "LEARNING_MIN_SAMPLE": 15,
  "AB_MIN_VIEWS_PER_ARM": 200,
  "AB_MIN_RELATIVE_LIFT": 0.2
};

const first = $input.first();
const incoming = first && first.json ? first.json : {};
const parentCfg = incoming.cfg && typeof incoming.cfg === 'object' ? incoming.cfg : {};

// ทั้ง $vars และ $env อาจไม่มีอยู่เลย (n8n Cloud) - แตะผ่าน try เท่านั้น
const readVars = (key) => {
  try {
    if (typeof $vars !== 'undefined' && $vars[key] !== undefined && $vars[key] !== '') {
      return $vars[key];
    }
  } catch (e) { /* Variables not available on this plan */ }
  return undefined;
};
const readEnv = (key) => {
  try {
    if (typeof $env !== 'undefined' && $env[key] !== undefined && $env[key] !== '') {
      return $env[key];
    }
  } catch (e) { /* env access blocked or not present */ }
  return undefined;
};

const cfg = {};
const sources = {};
for (const key of Object.keys(DEFAULTS)) {
  if (parentCfg[key] !== undefined) { cfg[key] = parentCfg[key]; sources[key] = 'parent'; continue; }
  const fromVars = readVars(key);
  if (fromVars !== undefined) { cfg[key] = fromVars; sources[key] = 'variables'; continue; }
  const fromEnv = readEnv(key);
  if (fromEnv !== undefined) { cfg[key] = fromEnv; sources[key] = 'env'; continue; }
  cfg[key] = DEFAULTS[key]; sources[key] = 'default';
}

return $input.all().map((item) => ({
  json: { ...item.json, cfg, cfg_sources: sources },
  binary: item.binary,
}));

// Central prompt library. Every OpenAI agent used by this workflow lives
// here so prompts are versioned with the workflow itself and can be
// diffed in git (mirrored in prompts/*.md).
const PROMPT_VERSION = $('Factory Config').first().json.cfg.PROMPT_VERSION || 'v1.0.0';
const PROMPTS = {
  "learning_ai": {
    "id": "learning_ai",
    "title": "Learning AI",
    "purpose": "Turn measured marketplace performance into concrete prompt improvements.",
    "system": "You are Learning AI. You read the measured performance of products this factory
already shipped and propose SPECIFIC, TESTABLE changes to the agent prompts.

Rules:
- Ground every recommendation in the numbers you were given. If the sample is
  too small to justify a change, say so and recommend `no_change`.
- A recommendation must name the agent, quote the sentence to change, and give
  the replacement sentence. "Be more creative" is not a recommendation.
- Never propose changes that would weaken a compliance rule (trademark checks,
  Etsy limits, age-appropriateness). Those are floors, not variables.
- `confidence` reflects sample size and effect size, not how good the idea feels.
- Prefer one high-conviction change over five speculative ones.
- Output valid JSON only.",
    "user_template": "WINDOW: {{window}}
PRODUCTS MEASURED: {{sample_size}}

PERFORMANCE BY CATEGORY:
{{category_performance_json}}

PERFORMANCE BY PROMPT VERSION:
{{prompt_performance_json}}

BEST PERFORMERS:
{{winners_json}}

WORST PERFORMERS:
{{losers_json}}

A/B TEST RESULTS THAT REACHED A CONCLUSION:
{{ab_results_json}}

Answer with the exact JSON contract.",
    "output_contract": "{
  "verdict": "change|no_change",
  "sample_adequate": true,
  "findings": ["string"],
  "recommendations": [
    {"agent": "string", "current_text": "string", "proposed_text": "string",
     "rationale": "string", "expected_effect": "string", "confidence": 0.0}
  ],
  "category_advice": [{"category": "string", "action": "more|less|hold", "why": "string"}],
  "next_ab_tests": [{"element": "title|thumbnail|description|price|tags", "hypothesis": "string"}]
}"
  },
  "ab_test_ai": {
    "id": "ab_test_ai",
    "title": "A/B Test AI",
    "purpose": "Author the challenger variant for one listing element.",
    "system": "You are A/B Test AI. You write the B variant for a single marketplace element so
that the test isolates ONE hypothesis.

Rules:
- Change only the element under test. Everything else stays identical.
- The variant must obey every marketplace limit the control obeys
  (title <= 140 characters, exactly 13 tags, each tag <= 20 characters).
- State the hypothesis in one sentence, in the form
  "If we <change>, then <metric> improves because <reason>".
- The variant must be meaningfully different - a synonym swap is not a test.
- For a price variant, stay inside the allowed price range you were given.
- Output valid JSON only.",
    "user_template": "ELEMENT UNDER TEST: {{element}}
CONTROL VALUE (variant A):
{{control_value}}

PRODUCT: {{product_name}}
CATEGORY: {{category}}
KEYWORDS: {{keywords}}
PRICE RANGE ALLOWED: {{price_range}}
WHAT PREVIOUS TESTS SHOWED:
{{prior_results}}

Write variant B. Answer with the exact JSON contract.",
    "output_contract": "{
  "element": "string",
  "hypothesis": "string",
  "variant_b": "string",
  "expected_metric": "views|favorites|conversion|revenue",
  "min_sample": 0
}"
  }
};

return $input.all().map((item) => ({
  json: { ...item.json, prompt_version: PROMPT_VERSION, prompts: PROMPTS },
}));

// Runs on a schedule or on demand. The window governs both what is measured and
// how much weight a conclusion deserves.
const input = $input.first() ? $input.first().json : {};
const windowDays = Math.max(1, Math.min(365, Number(input.window_days || $('Factory Config').first().json.cfg.LEARNING_WINDOW_DAYS || 30)));

return [{
  json: {
    run_id: input.run_id || `learn-${new Date().toISOString().slice(0, 10)}`,
    window_days: windowDays,
    window: `last ${windowDays} days`,
    marketplace: input.marketplace || 'etsy',
    prompt_version: $('Factory Config').first().json.cfg.PROMPT_VERSION || 'v1.0.0',
    dry_run: input.dry_run === true,
    started_at: new Date().toISOString(),
  },
}];

// Section 17: fold the shop receipts into per-listing sales and revenue.
// One call for the whole shop beats one call per listing.
const ctx = $('Normalize Learning Input').first().json;
const response = $input.first().json || {};
const receipts = response.results || [];

const byListing = new Map();
for (const receipt of receipts) {
  for (const tx of receipt.transactions || []) {
    const key = String(tx.listing_id || '');
    if (!key) continue;
    const row = byListing.get(key) || { sales: 0, revenue_usd: 0 };
    const amount = tx?.price?.amount;
    const divisor = tx?.price?.divisor || 100;
    row.sales += Number(tx.quantity || 1);
    row.revenue_usd += typeof amount === 'number' ? (amount / divisor) * Number(tx.quantity || 1) : 0;
    byListing.set(key, row);
  }
}

return [{
  json: {
    ...ctx,
    receipts_seen: receipts.length,
    sales_by_listing: Object.fromEntries(
      [...byListing.entries()].map(([k, v]) => [k, {
        sales: v.sales, revenue_usd: Math.round(v.revenue_usd * 100) / 100,
      }])
    ),
  },
}];

// One item per listing for the stats loop.
const listings = $('Postgres: Load Active Listings').all()
  .map((i) => i.json)
  .filter((row) => row && row.listing_id);

if (!listings.length) return [{ json: { no_listings: true } }];
return listings.map((json) => ({ json }));

// Section 17: views / favourites from the listing, sales from the receipts map.
const listing = $('Loop: Listings').first().json;
const stats = $('Aggregate Receipts').first().json;
const response = $input.first().json || {};

const detail = response.listing_id ? response : (response.results?.[0] || {});
const sold = stats.sales_by_listing?.[String(listing.listing_id)] || { sales: 0, revenue_usd: 0 };

const views = Number(detail.views || 0);
const favorites = Number(detail.num_favorers || 0);
// Etsy does not expose a click metric on this endpoint; favourites are the
// closest available proxy and are stored as such rather than invented.
const conversion = views > 0 ? Math.round((sold.sales / views) * 100000) / 1000 : 0;

return [{
  json: {
    marketplace: listing.marketplace,
    listing_id: String(listing.listing_id),
    run_id: listing.run_id,
    product_name: listing.product_name,
    category: listing.category,
    prompt_version: listing.prompt_version,
    views,
    clicks: favorites,
    favorites,
    sales: sold.sales,
    revenue_usd: sold.revenue_usd,
    conversion_rate: conversion,
  },
}];

// Pack every measured listing into one array for a single bulk upsert.
const ctx = $('Normalize Learning Input').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.listing_id);
const collectedAt = new Date().toISOString();

return [{
  json: {
    ...ctx,
    collected_at: collectedAt,
    listing_count: rows.length,
    rows_json: JSON.stringify(rows.map((r) => ({ ...r, collected_at: collectedAt }))),
    totals: {
      views: rows.reduce((s, r) => s + r.views, 0),
      favorites: rows.reduce((s, r) => s + r.favorites, 0),
      sales: rows.reduce((s, r) => s + r.sales, 0),
      revenue_usd: Math.round(rows.reduce((s, r) => s + r.revenue_usd, 0) * 100) / 100,
    },
  },
}];

// Section 21: decide running A/B tests. Deliberately conservative - a test is
// only called when both arms have enough traffic and the gap is not noise.
const ctx = $('Normalize Learning Input').first().json;
const row = $input.first().json || {};

const asArray = (value) => {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') { try { return JSON.parse(value); } catch (e) { return []; } }
  return value || [];
};

const MIN_VIEWS = Number($('Factory Config').first().json.cfg.AB_MIN_VIEWS_PER_ARM || 200);
const MIN_LIFT = Number($('Factory Config').first().json.cfg.AB_MIN_RELATIVE_LIFT || 0.20);

const tests = asArray(row.ab_tests);
const grouped = new Map();
for (const arm of tests) {
  const list = grouped.get(arm.test_uid) || [];
  list.push(arm);
  grouped.set(arm.test_uid, list);
}

const decisions = [];
for (const [testUid, arms] of grouped) {
  const a = arms.find((x) => x.variant === 'A');
  const b = arms.find((x) => x.variant === 'B');
  if (!a || !b) continue;

  const rate = (arm) => (arm.views > 0 ? arm.sales / arm.views : 0);
  const rateA = rate(a);
  const rateB = rate(b);

  if (a.views < MIN_VIEWS || b.views < MIN_VIEWS) {
    decisions.push({ test_uid: testUid, element: a.element, decision: 'keep_running',
                     reason: `needs ${MIN_VIEWS} views per arm (A=${a.views}, B=${b.views})` });
    continue;
  }

  const lift = rateA > 0 ? (rateB - rateA) / rateA : (rateB > 0 ? 1 : 0);
  if (Math.abs(lift) < MIN_LIFT) {
    decisions.push({ test_uid: testUid, element: a.element, decision: 'no_difference',
                     winner: 'A', reason: `relative lift ${Math.round(lift * 1000) / 10}% is inside the noise band` });
  } else {
    decisions.push({
      test_uid: testUid, element: a.element,
      decision: 'winner', winner: lift > 0 ? 'B' : 'A',
      reason: `variant ${lift > 0 ? 'B' : 'A'} converts ${Math.abs(Math.round(lift * 1000) / 10)}% better`,
      winning_value: lift > 0 ? b.variant_value : a.variant_value,
    });
  }
}

return [{
  json: {
    ...ctx,
    performance: {
      categories: asArray(row.categories),
      marketplaces: asArray(row.marketplaces),
      prompts: asArray(row.prompts),
      winners: asArray(row.winners),
      losers: asArray(row.losers),
      sample_size: Number(row.sample_size || 0),
    },
    ab_decisions: decisions,
    ab_concluded: decisions.filter((d) => d.decision !== 'keep_running'),
  },
}];

// Mustache-style renderer for the {{placeholders}} in the prompt templates.
const render = (template, vars) =>
  String(template).replace(/\{\{\s*(\w+)\s*\}\}/g, (_, key) =>
    vars[key] === undefined || vars[key] === null ? '' : String(vars[key]));

const ctx = $input.first().json;
const agent = $('Prompt Library').first().json.prompts.learning_ai;
const perf = ctx.performance;

return [{
  json: {
    ...ctx,
    learning_user_prompt: render(agent.user_template, {
      window: ctx.window,
      sample_size: perf.sample_size,
      category_performance_json: JSON.stringify(perf.categories, null, 2),
      prompt_performance_json: JSON.stringify(perf.prompts, null, 2),
      winners_json: JSON.stringify(perf.winners, null, 2),
      losers_json: JSON.stringify(perf.losers, null, 2),
      ab_results_json: JSON.stringify(ctx.ab_concluded, null, 2),
    }),
  },
}];

